def submit_sequenced_transaction(
    self, payload: object
) -> tuple[int, dict]:
    """POST /v1/transactions/sequenced — validate and reserve a sequenced
    transfer. Returns ``(status, body)``.

    The payload is exactly ``{from, to, amount, nonce, signature}``:
    ``from``/``to`` non-empty strings, ``amount`` a positive non-boolean
    integer, ``nonce`` a non-negative non-boolean integer and ``signature``
    a non-empty string; the signed message is
    ``ledger-sequenced-transfer-v1\\n{"amount":A,"from":F,"nonce":N,"to":T}``
    and the signing key must derive ``from``. Every field, type,
    signature or balance defect is ``400 {"error": "input"}``.

    Sequencing: ``nonce`` must equal the account's current
    ``next_sequence`` (the dense prefix of confirmed nonces plus the
    contiguous pending-tip/mempool reservations). A smaller nonce that
    names a different transaction, or any nonce past the next one (a
    gap), is ``409 {"error": "sequence_conflict", "next_sequence": N}``.
    A retried identical request (same from/to/amount/nonce/signature,
    hence same tx_id) is idempotent: it replays the first result with
    status 200 and no new state or audit event, whether the transfer is
    still queued, packed into the pending tip or already confirmed.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "input"}
    for field in REQUIRED_SEQUENCED_TX_FIELDS:
        if field not in payload:
            return 400, {"error": "input"}

    sender = payload["from"]
    recipient = payload["to"]
    amount = payload["amount"]
    nonce = payload["nonce"]
    signature = payload["signature"]

    if not isinstance(sender, str) or not sender:
        return 400, {"error": "input"}
    if not isinstance(recipient, str) or not recipient:
        return 400, {"error": "input"}
    # bool is a subclass of int: reject it and all non-int types explicitly.
    if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        return 400, {"error": "input"}
    # bool is likewise rejected for nonce; negatives and non-ints too.
    if isinstance(nonce, bool) or not isinstance(nonce, int) or nonce < 0:
        return 400, {"error": "input"}
    if not isinstance(signature, str) or not signature:
        return 400, {"error": "input"}

    message = crypto.sequenced_message(sender, recipient, amount, nonce)
    if not crypto.verify_signature(sender, message, signature):
        return 400, {"error": "input"}

    tx = Transaction(sender, recipient, amount, signature, nonce)
    with self.store.lock:
        # Idempotent retries are decided before any sequence or balance
        # gate: the same signed request (same tx_id) always returns the
        # original result, whether it is queued, packed unconfirmed or
        # confirmed, and never appends a second transaction_submitted
        # event.
        existing_status = self._sequenced_tx_location(tx.tx_id)
        if existing_status is not None:
            return 200, {"tx_id": tx.tx_id, "nonce": nonce}

        # A different transaction already occupying this (sender, nonce)
        # slot, or a nonce past the next acceptable value, is a sequence
        # conflict naming the current next_sequence.
        state = self.store.sequences.get(sender)
        next_sequence = self.store.sequence_next(state)
        if nonce != next_sequence:
            return 409, {
                "error": "sequence_conflict",
                "next_sequence": next_sequence,
            }
        # Balance is checked exactly like a legacy submission against
        # the available (confirmed minus pending-tip and mempool spends)
        # balance; sequenced reservations spend like any mempool entry.
        if self.available_balance(sender) < amount:
            return 400, {"error": "input"}
        self.store.pending[tx.tx_id] = tx
        # First successful reservation: one transaction_submitted event
        # (carrying nonce), persisted in the same atomic write as the
        # mempool change.
        self.store.append_audit_event(
            EVENT_TRANSACTION_SUBMITTED,
            {
                "tx_id": tx.tx_id,
                "from": tx.sender,
                "to": tx.recipient,
                "amount": tx.amount,
                "nonce": tx.nonce,
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Persistence failed: drop the in-memory reservation and its
            # event so memory keeps matching the last committed state.
            self.store.pending.pop(tx.tx_id, None)
            self.store.truncate_audit_events(1)
            raise
    return 202, {"tx_id": tx.tx_id, "nonce": nonce}

def _validate_sequenced_batch(
    self, payload: object
) -> tuple[int, dict | None, list[Transaction] | None]:
    """Validate a sequenced-batch request body.

    Returns ``(None, None, transactions)`` when the shape, types and
    signatures are all sound, otherwise ``(status, body, None)``. The
    envelope is exactly ``{"transactions": [item, ...]}`` with a
    non-empty list; each item carries exactly the five single-entry
    fields with the single-entry types. Field/type and signature defects
    are ``400 {"error": "input", "index": I}`` at the first offending
    item; envelope defects are ``400 {"error": "input"}``.
    """
    if not isinstance(payload, dict) or set(payload) != {"transactions"}:
        return 400, {"error": "input"}, None
    items = payload["transactions"]
    if not isinstance(items, list) or not items:
        return 400, {"error": "input"}, None
    transactions: list[Transaction] = []
    for index, item in enumerate(items):
        if not isinstance(item, dict) or set(item) != set(
            REQUIRED_SEQUENCED_TX_FIELDS
        ):
            return 400, {"error": "input", "index": index}, None
        sender = item["from"]
        recipient = item["to"]
        amount = item["amount"]
        nonce = item["nonce"]
        signature = item["signature"]
        if not isinstance(sender, str) or not sender:
            return 400, {"error": "input", "index": index}, None
        if not isinstance(recipient, str) or not recipient:
            return 400, {"error": "input", "index": index}, None
        if (
            isinstance(amount, bool)
            or not isinstance(amount, int)
            or amount <= 0
        ):
            return 400, {"error": "input", "index": index}, None
        if (
            isinstance(nonce, bool)
            or not isinstance(nonce, int)
            or nonce < 0
        ):
            return 400, {"error": "input", "index": index}, None
        if not isinstance(signature, str) or not signature:
            return 400, {"error": "input", "index": index}, None
        message = crypto.sequenced_message(sender, recipient, amount, nonce)
        if not crypto.verify_signature(sender, message, signature):
            return 400, {"error": "input", "index": index}, None
        transactions.append(
            Transaction(sender, recipient, amount, signature, nonce)
        )
    return None, None, transactions

def submit_sequenced_batch(
    self, payload: object
) -> tuple[int, dict]:
    """POST /v1/transactions/sequenced/batch — atomically reserve a batch
    of nonce-ordered sequenced transfers. Returns ``(status, body)``.

    The body is exactly ``{"transactions": [item, ...]}`` with a
    non-empty list; every item is signed exactly like
    ``submit_sequenced_transaction``. The batch succeeds only when every
    item passes together under the store lock and lands in a single
    atomic write; a rejected batch changes no state.

    Checks run in this order and the first offending item (smallest
    input index) is reported:

    * field/type defects and bad signatures are
      ``400 {"error": "input", "index": I}`` (envelope defects carry no
      index);
    * a repeated ``(sender, nonce)`` inside the batch is
      ``400 {"error": "input", "index": I}``, and so is an internal gap
      in a sender's fresh batch nonces;
    * a batch starting above the live ``next_sequence`` or carrying a
      different transaction on an occupied nonce is
      ``409 {"error": "sequence_conflict", "index": I,
      "next_sequence": N}``;
    * a sender's total batch spend (replayed items excluded) over the
      available balance — confirmed balance minus every pending-tip and
      mempool spend, unconfirmed credits never counted — is
      ``409 {"error": "insufficient_balance", "index": I}``;
    * an item whose tx_id already exists while the batch is not an exact
      whole-batch replay is
      ``409 {"error": "transaction_exists", "index": I}``.

    Every item already existing replays the batch: 200 with ``items``
    (each ``{tx_id, nonce, location}`` in request order, ``location``
    pending/confirmed) and ``total``, touching no state. A first
    successful batch answers 202 with ``items`` (each
    ``{tx_id, nonce}``) and ``total``; each newly admitted transaction
    appends one ``transaction_submitted`` event in the same atomic
    write, whose failure answers ``500 {"error": "persistence failed"}``
    after restoring the pre-request state.
    """
    status, error, transactions = self._validate_sequenced_batch(payload)
    if status is not None:
        return status, error  # type: ignore[return-value]
    assert transactions is not None
    txs = transactions

    with self.store.lock:
        # Per-sender nonce placement visited in request order; items of
        # different senders may interleave freely. Tracked per sender:
        # the next expected nonce (live dense prefix extended by the
        # batch slots accepted so far), whether the batch has filled any
        # fresh slot for the sender, and the batch nonces seen.
        #
        # * a live slot (< next_sequence) holding this same tx_id is a
        #   replay item; holding a different transaction is a reservation
        #   conflict (409);
        # * the sender's first fresh batch slot must equal next_sequence,
        #   otherwise the batch starts misaligned (409);
        # * once batch slots were filled, a jump over or back before the
        #   current expectation is an in-batch gap/duplicate (400).
        #
        # The 400 category wins across senders; within one category the
        # smallest input index is reported.
        existing: list[bool] = [False] * len(txs)
        gap_index: int | None = None
        conflict_index: int | None = None
        conflict_next: dict[str, int] = {}
        per_sender: dict[str, dict] = {}
        for index, tx in enumerate(txs):
            state = self.store.sequences.get(tx.sender)
            next_sequence = self.store.sequence_next(state)
            track = per_sender.setdefault(
                tx.sender,
                {"expected": next_sequence, "started": False, "seen": set()},
            )
            if tx.nonce in track["seen"]:
                if gap_index is None:
                    gap_index = index
                continue
            track["seen"].add(tx.nonce)
            if tx.nonce < next_sequence:
                occupant = None
                if state is not None:
                    occupant = state["confirmed"].get(tx.nonce)
                    if occupant is None:
                        occupant = state["pending"].get(tx.nonce)
                if occupant == tx.tx_id:
                    existing[index] = True
                elif conflict_index is None or index < conflict_index:
                    conflict_index = index
                    conflict_next[tx.sender] = next_sequence
            elif not track["started"]:
                if tx.nonce != next_sequence:
                    if conflict_index is None or index < conflict_index:
                        conflict_index = index
                        conflict_next[tx.sender] = next_sequence
                track["expected"] = tx.nonce + 1
                track["started"] = True
            elif tx.nonce == track["expected"]:
                track["expected"] = tx.nonce + 1
            elif gap_index is None:
                # After the batch reserved slots for this sender, the
                # next item skips a nonce or names one already passed.
                gap_index = index
        if gap_index is not None:
            return 400, {"error": "input", "index": gap_index}
        if conflict_index is not None:
            sender = txs[conflict_index].sender
            return 409, {
                "error": "sequence_conflict",
                "index": conflict_index,
                "next_sequence": conflict_next.get(sender, 0),
            }

        # Balance is the single-entry gate summed per sender over the
        # whole batch, replayed items excluded (their spend is already
        # deducted from the mempool/chain view). Items are visited in
        # request order so the first over-drawing item names the index.
        batch_spend: dict[str, int] = {}
        for index, tx in enumerate(txs):
            if existing[index]:
                continue
            spent = batch_spend.get(tx.sender, 0) + tx.amount
            if self.available_balance(tx.sender) - spent < 0:
                return 409, {
                    "error": "insufficient_balance",
                    "index": index,
                }
            batch_spend[tx.sender] = spent

        # Partial overlap: after every other gate, a live item outside a
        # whole-batch replay is rejected.
        if any(existing) and not all(existing):
            return 409, {
                "error": "transaction_exists",
                "index": existing.index(True),
            }

        if all(existing):
            items = [
                {
                    "tx_id": tx.tx_id,
                    "nonce": tx.nonce,
                    "location": self._sequenced_tx_location(tx.tx_id),
                }
                for tx in txs
            ]
            return 200, {"items": items, "total": len(items)}

        for tx in txs:
            self.store.pending[tx.tx_id] = tx
            self.store.append_audit_event(
                EVENT_TRANSACTION_SUBMITTED,
                {
                    "tx_id": tx.tx_id,
                    "from": tx.sender,
                    "to": tx.recipient,
                    "amount": tx.amount,
                    "nonce": tx.nonce,
                },
            )
        try:
            self.store.save()
        except BaseException:
            for tx in txs:
                self.store.pending.pop(tx.tx_id, None)
            self.store.truncate_audit_events(len(txs))
            return 500, {"error": "persistence failed"}
        items = [{"tx_id": tx.tx_id, "nonce": tx.nonce} for tx in txs]
        return 202, {"items": items, "total": len(items)}

def _sequenced_tx_location(self, tx_id: str) -> str | None:
    """Locate a tx_id across the canonical chain and mempool.

    Returns ``"confirmed"`` when it is in a confirmed block,
    ``"pending"`` when it is in the unconfirmed tip or the mempool, or
    None when nothing holds it. Caller must hold the store lock.
    """
    for block in self.store.chain:
        if any(tx.tx_id == tx_id for tx in block.transactions):
            return (
                STATUS_CONFIRMED
                if block.status == STATUS_CONFIRMED
                else STATUS_PENDING
            )
    if tx_id in self.store.pending:
        return STATUS_PENDING
    return None

def get_account_sequence(self, account: object) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/sequence — the account's nonce stream.

    Returns ``{account, next_sequence, pending_sequences,
    confirmed_sequences}``; the two arrays list ``{nonce, tx_id}`` pairs
    ascending by nonce. An account that has never sent a sequenced
    transfer (a "stranger") still answers 200 with next_sequence 0 and
    empty arrays. A non-string or empty account is 400 input.
    """
    if not isinstance(account, str) or not account:
        return 400, {"error": "input"}
    with self.store.lock:
        state = self.store.sequences.get(account)
        if state is None:
            return 200, {
                "account": account,
                "next_sequence": 0,
                "pending_sequences": [],
                "confirmed_sequences": [],
            }
        confirmed = [
            {"nonce": nonce, "tx_id": state["confirmed"][nonce]}
            for nonce in sorted(state["confirmed"])
        ]
        reserved = [
            {"nonce": nonce, "tx_id": state["pending"][nonce]}
            for nonce in sorted(state["pending"])
        ]
        return 200, {
            "account": account,
            "next_sequence": self.store.sequence_next(state),
            "pending_sequences": reserved,
            "confirmed_sequences": confirmed,
        }

def get_transaction(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id} — one transaction receipt.

    The lookup covers the canonical chain and the mempool only; candidate
    forks are never exposed. A ``tx_id`` that is not exactly 64 lowercase
    hex characters, or one nothing holds, returns 404.

    A mempool transaction is reported ``pending`` with ``height``,
    ``block_hash`` and ``index`` all null. A transaction packed into the
    unconfirmed tip block is ``pending`` too, anchored at that block with
    its 0-based in-block index. A transaction in a confirmed block is
    ``confirmed``. Every receipt is built from the stored signed
    transaction: the id is recomputed from its canonical message (never
    taken from an index or a fork-side cache) and the fields are strictly
    re-typed (non-empty strings, a positive non-boolean integer amount),
    so adoption, rollback and restart can only ever surface the current
    canonical/pending state.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        # Canonical chain first: confirmed blocks, then at most one
        # pending tip. The stored signed transaction is the sole source
        # for the receipt, and its id is recomputed rather than trusted
        # from any lookup key.
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id != tx_id:
                    continue
                if not self._is_receipt_tx_well_typed(tx):
                    return 404, {"error": "transaction not found"}
                status = (
                    STATUS_CONFIRMED
                    if block.status == STATUS_CONFIRMED
                    else STATUS_PENDING
                )
                return 200, self._transaction_receipt(
                    tx, status, block.height, block.block_hash, index
                )
        # Still unpacked in the mempool.
        tx = self.store.pending.get(tx_id)
        if tx is not None:
            if not self._is_receipt_tx_well_typed(tx):
                return 404, {"error": "transaction not found"}
            return 200, self._transaction_receipt(
                tx, STATUS_PENDING, None, None, None
            )
        return 404, {"error": "transaction not found"}

@staticmethod
def _is_receipt_tx_well_typed(tx: Transaction) -> bool:
    """Strict receipt-time type check of a stored signed transaction.

    Every stored transaction already passed these checks at submission
    (and again during snapshot recovery); the re-check guarantees a
    receipt can never serialize a value that violates the response
    contract, even if an in-memory invariant were broken.
    """
    return (
        isinstance(tx.sender, str)
        and bool(tx.sender)
        and isinstance(tx.recipient, str)
        and bool(tx.recipient)
        and isinstance(tx.amount, int)
        and not isinstance(tx.amount, bool)
        and tx.amount > 0
        and isinstance(tx.signature, str)
        and bool(tx.signature)
        and (
            tx.nonce is None
            or (isinstance(tx.nonce, int) and not isinstance(tx.nonce, bool) and tx.nonce >= 0)
        )
    )

@staticmethod
def _transaction_receipt(
    tx: Transaction,
    status: str,
    height: int | None,
    block_hash: str | None,
    index: int | None,
) -> dict:
    """The fixed nine-field receipt shape for legacy transfers.

    A sequenced transfer appends one further field, ``nonce`` (its
    non-negative sequence number), after ``index``; a legacy transfer
    keeps the exact nine-field document unchanged.
    """
    receipt = {
        "tx_id": tx.tx_id,
        "from": tx.sender,
        "to": tx.recipient,
        "amount": tx.amount,
        "signature": tx.signature,
        "status": status,
        "height": height,
        "block_hash": block_hash,
        "index": index,
    }
    if tx.nonce is not None:
        receipt["nonce"] = tx.nonce
    return receipt

# At most this many distinct ids are accepted by one batch receipt query.
RECEIPTS_MAX_TX_IDS = 200

def get_transaction_receipts(self, payload: object) -> tuple[int, dict]:
    """POST /v1/transactions/receipts — a batch of ordinary transaction
    receipts against one persisted ledger state.

    The body must be a JSON object containing exactly the ``tx_ids``
    key: an array of between one and ``RECEIPTS_MAX_TX_IDS`` distinct
    strings, each exactly 64 lowercase hex characters. Every other
    shape — a non-object body, a missing or extra key, a non-array or
    out-of-range array, a malformed element, or a duplicate — is 400

def _compute_derived(self) -> tuple[dict[str, int], dict[str, dict], dict[str, dict]]:
    """Build the confirmed-only transaction index, account activity and
    per-account sequence state.

    Pending blocks are excluded from balances/tx index: only confirmed
    blocks contribute there. The sequence state additionally covers the
    unconfirmed pending tip block and the mempool, since a packed-but-
    unconfirmed sequenced transfer keeps reserving its sender nonce until
    its block is confirmed or rolled back (a rollback returns it to the
    mempool reservation it already held). Pure: it returns fresh dicts and
    never mutates store state, so callers can compute a prospective view
    and publish it only after a successful write.
    """
    tx_index: dict[str, int] = {}
    accounts: dict[str, dict] = {}
    sequences = self.compute_sequence_state(self.chain, self.pending)
    for block in self.chain:
        if block.status != STATUS_CONFIRMED:
            continue
        for tx in block.transactions:
            tx_index[tx.tx_id] = block.height
            for account in (tx.sender, tx.recipient):
                entry = accounts.setdefault(
                    account, {"sent": 0, "received": 0, "transactions": []}
                )
                entry["transactions"].append(tx.tx_id)
            accounts[tx.sender]["sent"] += tx.amount
            accounts[tx.recipient]["received"] += tx.amount
    return tx_index, accounts, sequences

@staticmethod
def compute_sequence_state(
    chain: list[Block], pending: dict[str, Transaction]
) -> dict[str, dict]:
    """Per-sender sequenced-transfer state derived from chain and mempool.

    The result maps each sender that owns at least one sequenced transfer
    to ``{"confirmed": {nonce: tx_id}, "pending": {nonce: tx_id}}`` where
    *confirmed* covers the sender's nonces in confirmed blocks and
    *pending* covers every other live reservation: sequenced transfers in
    the unconfirmed pending tip block plus sequenced transfers still in the
    mempool (including ones a fork adoption returned there). Legacy
    transactions (``nonce is None``) never appear. Every other account is
    absent and reads as sequence 0 with empty lists.

    Two different transactions reserving the same sender nonce are an
    invariant violation (the service answers 409 for them) and raise
    ValueError, so recovery can turn them into a fatal snapshot defect.
    """
    state: dict[str, dict] = {}

    def slot(account: str) -> dict:
        return state.setdefault(account, {"confirmed": {}, "pending": {}})

    def place(bucket: dict, account: str, nonce: int, tx_id: str) -> None:
        existing = bucket.get(nonce)
        if existing is not None and existing != tx_id:
            raise ValueError(
                f"sequenced nonce {nonce} for sender {account} is reserved "
                f"by two different transactions: {existing} and {tx_id}"
            )
        bucket[nonce] = tx_id

    for block in chain:
        bucket_name = "confirmed" if block.status == STATUS_CONFIRMED else "pending"
        for tx in block.transactions:
            if tx.nonce is None:
                continue
            place(slot(tx.sender)[bucket_name], tx.sender, tx.nonce, tx.tx_id)
    for tx in pending.values():
        if tx.nonce is None:
            continue
        entry = slot(tx.sender)
        if tx.nonce in entry["confirmed"]:
            # The same id may legitimately sit nowhere twice; a different
            # transaction holding the confirmed nonce is a clash.
            if entry["confirmed"][tx.nonce] != tx.tx_id:
                raise ValueError(
                    f"sequenced nonce {tx.nonce} for sender {tx.sender} is "
                    f"both confirmed ({entry['confirmed'][tx.nonce]}) and "
                    f"pending ({tx.tx_id})"
                )
            continue
        place(entry["pending"], tx.sender, tx.nonce, tx.tx_id)
    return state

@staticmethod
def sequence_next(state: dict | None) -> int:
    """The next acceptable nonce: one past the dense confirmed/pending set.

    Valid reservations always form a dense prefix ``0..k-1`` (enforced on
    submission, fork validation and recovery), so the next nonce is the
    size of the confirmed-or-reserved nonce set, equivalently the smallest
    missing nonce.
    """
    if state is None:
        return 0
    return len(state["confirmed"]) + len(state["pending"])

@staticmethod
def validate_sequence_partitions(
    state: dict[str, dict], path: str | None = None
) -> None:
    """Require each sender's nonces to be two dense, abutting partitions.

    The confirmed nonces must be exactly ``{0, ..., c-1}`` (confirmation
    never skips or rewinds a nonce) and every still-reserved nonce exactly
    ``{c, ..., c+p-1}`` (pending-tip and mempool reservations continue the
    confirmed prefix with no gap). Raises ValueError, or
    StateRecoveryError when ``path`` is given, on the first violation.
    """

    def fail(reason: str):
        if path is not None:
            raise StateRecoveryError(path, reason)
        raise ValueError(reason)

    for account, entry in sorted(state.items()):
        confirmed = entry["confirmed"]
        reserved = entry["pending"]
        overlap = set(confirmed) & set(reserved)
        if overlap:
            fail(
                f"sequenced nonce(s) {sorted(overlap)} for sender {account} "
                "are both confirmed and pending"
            )
        c_count = len(confirmed)
        if set(confirmed) != set(range(c_count)):
            fail(
                f"confirmed sequenced nonces for sender {account} are not a "
                f"dense prefix 0..{c_count - 1}"
            )
        p_count = len(reserved)
        if set(reserved) != set(range(c_count, c_count + p_count)):
            fail(
                f"pending sequenced nonces for sender {account} do not "
                f"continue the confirmed prefix {c_count} without a gap"
            )

def rebuild_derived(self) -> None:
    """Rebuild the confirmed-only transaction index, account activity and
    per-account sequence state.

    Pending blocks are excluded from balances and the tx index; the
    sequence state keeps the pending tip's nonces reserved.
    """
    self.tx_index, self.accounts, self.sequences = self._compute_derived()

@staticmethod
def account_state_rows(
    chain: list[Block], initial_balance: int
) -> list[tuple[str, int, list[str]]]:
    """Confirmed account-state rows ordered by ascending account id.

    Only confirmed blocks contribute, so the result is independent of any
    pending tip block. Each row is ``(account, confirmed_balance, T)``
    where ``T`` is the account's confirmed transaction ids in their
    original on-chain order.
    """
    activity: dict[str, dict] = {}

def _validate_ledger_lifecycle_events(
    self,
    audit_events: list[dict],
    chain: list[Block],
    pending: dict[str, Transaction],
